import { requireExportContext } from '@/lib/auth'
import { productionList } from '@/lib/approvals/production'
import { recordAuditInTransaction } from '@/lib/audit'
function cell(value:unknown) {
  const text=String(value??'')
  return '"'+(/^[=+@\-\t\r\n]/.test(text)?"'"+text:text).replaceAll('"','""')+'"'
}
export async function GET(request:Request) {
  const ctx=await requireExportContext(),sp=new URL(request.url).searchParams
  try {
    const csv=await ctx.db(async tx=>{
      const data=await productionList({...ctx,db:async fn=>fn(tx)},{view:'reports',q:(sp.get('q')??'').slice(0,200),status:sp.get('status')??'',propertyId:sp.get('property')??'',page:1,perPage:10001})
      if(data.total>10000)throw new Error('Narrow the report to 10000 requests or fewer')
      await recordAuditInTransaction(tx,ctx,{entityType:'approval_report',entityId:ctx.tenantId,action:'export',summary:'Approvals report exported',metadata:{count:data.total}})
      const keys=['id','title','property_name','category','amount','currency','supplier','status','created_at']
      return [keys.map(cell).join(','),...data.rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')
    })
    return new Response(csv,{headers:{'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="approvals.csv"','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}})
  } catch{return new Response('Export unavailable. Check your export authority or narrow the report to 10,000 requests or fewer.',{status:400})}
}

