// Canonical registry of built-in app modules.
//
// This is the single source of truth for the left-hand navigation. The
// resolver (./resolve.ts) merges this with a tenant's saved overrides
// (tenant_nav_config) to produce the rendered sidebar; the in-UI editor
// (/admin/navigation) lists these as the modules an admin can show / hide /
// reorder / re-label.
//
// Pure data + helpers only — no server imports — so the client editor can
// import it too. `TenantNavConfig` is a type-only import (erased at build).

import type { TenantNavConfig } from '@beaconhs/db/schema'

type NavModule = {
  /** Stable id, referenced by NavItemConfig.moduleKey. Never change once shipped. */
  key: string
  boardHidden?: boolean
  href: string
  label: string
  /** Key into the ICONS map in components/sidebar-nav.tsx. */
  iconKey: string
  /**
   * Permission required to see this module. Checked with `can(ctx, perm)`
   * (wildcard-aware). Undefined = always visible. Sensitive/admin-adjacent
   * modules should use explicit permissions so roles can deliberately opt in.
   */
  requiredPermission?: string
  /**
   * At least one of these permissions is required to see this module. Useful for
   * hub routes where several independently gated tools live behind one entry.
   */
  requiredAnyPermission?: string[]
  /** Default group label — must be one of NAV_GROUP_ORDER. */
  group: (typeof NAV_GROUP_ORDER)[number]
}

const NAV_MODULE_MESSAGE_KEYS: Record<string, string> = {
  dashboard: 'Nav.modules.dashboard',
  assistant: 'Nav.modules.assistant',
  feed: 'Nav.modules.feed',
  my: 'Nav.modules.my',
  notifications: 'Nav.modules.notifications',
  inspections: 'Nav.modules.inspections',
  journals: 'Nav.modules.journals',
  incidents: 'Nav.modules.incidents',
  'corrective-actions': 'Nav.modules.correctiveActions',
  tools: 'Nav.modules.tools',
  training: 'Nav.modules.training',
  documents: 'Nav.modules.documents',
  help: 'Nav.modules.help',
  people: 'Nav.modules.people',
  locations: 'Nav.modules.locations',
  equipment: 'Nav.modules.equipment',
  ppe: 'Nav.modules.ppe',
  compliance: 'Nav.modules.compliance',
  insights: 'Nav.modules.insights',
  reports: 'Nav.modules.reports',
  admin: 'Nav.modules.admin',
  forms: 'Nav.modules.forms',
}

// Group order top-to-bottom.
const NAV_GROUP_ORDER = [
  'Overview',
  'Frontline',
  'Knowledge',
  'Assets & people',
  // Program oversight — obligations/compliance + analytics/dashboards + reports.
  'Assurance',
  'Administration',
] as const

const NAV_GROUP_MESSAGE_KEYS: Record<(typeof NAV_GROUP_ORDER)[number], string> = {
  Overview: 'Nav.groups.overview',
  Frontline: 'Nav.groups.frontline',
  Knowledge: 'Nav.groups.knowledge',
  'Assets & people': 'Nav.groups.assetsPeople',
  Assurance: 'Nav.groups.assurance',
  Administration: 'Nav.groups.administration',
}

export function defaultNavGroupMessageKey(id: string, label: string): string | undefined {
  const defaultLabel = NAV_GROUP_ORDER.find((candidate) => defaultGroupId(candidate) === id)
  return defaultLabel === label ? NAV_GROUP_MESSAGE_KEYS[defaultLabel] : undefined
